", \"Program Administrator\"], \"/esdc/participants\": [\"System Administrator\", \"Program Administrator\"], \"/manage-components\": [\"System Administrator\", \"Program Administrator\"], \"/finance/monitoring\": [\"System Administrator\", \"Program Administrator\"], \"/admin/upload-config\": [\"System Administrator\", \"Program Administrator\"], \"/finance/allocations\": [\"System Administrator\", \"Program Administrator\"], \"/finance/forecasting\": [\"System Administrator\", \"Program Administrator\"], \"/nwac-hub-management\": [\"System Administrator\"], \"/reporting-dashboard\": [\"System Administrator\"], \"/tutorials-dashboard\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/application-case/:id\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/audit-logs-dashboard\": [\"System Administrator\"], \"/configuration/events\": [\"System Administrator\", \"Program Administrator\"], \"/manage-notifications\": [\"System Administrator\", \"Program Administrator\"], \"/modify-component/:id\": [\"System Administrator\", \"Program Administrator\"], \"/configuration-settings\": [\"System Administrator\", \"Program Administrator\"], \"/contact-communications\": [\"System Administrator\", \"Program Administrator\"], \"/finance/reconciliation\": [\"System Administrator\", \"Program Administrator\"], \"/help-support-dashboard\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/manage-security-options\": [\"System Administrator\", \"Program Administrator\"], \"/service-levels-dashboard\": [\"System Administrator\"], \"/case-assignment-dashboard\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\", \"Application Assessor\"], \"/user-management-dashboard\": [\"System Administrator\", \"Program Administrator\", \"Regional Coordinator\"], \"/capacity-planning-dashboard\": [\"System Administrator\"], \"/custom-dashboards-dashboard\": [\"System Administrator\"], \"/language-settings-dashboard\": [\"System Administrator\"], \"/release-management-dashboard\": [\"System Administrator\"], \"/system-performance-dashboard\": [\"System Administrator\"], \"/reporting-and-monitoring-dashboard\": [\"System Administrator\"], \"/case-assignment-dashboard?view=assignment\": [\"System Administrator\"]}, \"default\": \"deny\"}','2025-10-27 08:59:13'),(58,'publish','workflow.schema.intake','{\"meta\": {\"checksum\": \"4a01019b285ec034bf9cd6587cea8842a81a6ae4b277ede4c588ae7981821ead\", \"schemaMeta\": {\"counts\": {\"steps\": 22, \"components\": 114}, \"workflow\": {\"id\": 21, \"name\": \"ISET Intake Testing\", \"status\": \"active\"}, \"templates\": [{\"id\": 29, \"type\": \"paragraph\", \"count\": 42, \"version\": 1, \"template_key\": \"text-block\"}, {\"id\": 35, \"type\": \"signature-ack\", \"count\": 3, \"version\": 1, \"template_key\": \"signature-ack\"}, {\"id\": 1, \"type\": \"radio\", \"count\": 19, \"version\": 1, \"template_key\": \"radio\"}, {\"id\": 26, \"type\": \"input\", \"count\": 36, \"version\": 1, \"template_key\": \"input\"}, {\"id\": 13, \"type\": \"date-input\", \"count\": 1, \"version\": 1, \"template_key\": \"date-input\"}, {\"id\": 2, \"type\": \"select\", \"count\": 1, \"version\": 1, \"template_key\": \"select\"}, {\"id\": 32, \"type\": \"textarea\", \"count\": 2, \"version\": 1, \"template_key\": \"textarea\"}, {\"id\": 31, \"type\": \"character-count\", \"count\": 2, \"version\": 1, \"template_key\": \"character-count\"}, {\"id\": 33, \"type\": \"checkbox\", \"count\": 2, \"version\": 1, \"template_key\": \"checkbox\"}, {\"id\": 24, \"type\": \"summary-list\", \"count\": 6, \"version\": 1, \"template_key\": \"summary-list\"}, {\"id\": 19, \"type\": \"file-upload\", \"count\": 6, \"version\": 1, \"template_key\": \"file-upload\"}], \"generatedAt\": \"2025-10-17T18:28:24.907Z\", \"schemaVersion\": \"1.1\"}, \"workflowId\": 21, \"generatedAt\": \"2025-10-17T18:28:24.909Z\"}, \"schema\": [{\"type\": \"schema\", \"title\": {\"en\": \"Consent\", \"fr\": \"Consent\"}, \"stepId\": \"consent\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Consent Form\", \"fr\": \"Formulaire de consentement\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"By proceeding, I give my expressed and informed consent to the Native Women’s Association of Canada and/or its sub-agreement holders to the Indigenous Skills and Employment Training Program (hereinafter referred to as ISET), to collect personal or sensitive information as it relates to my request for funding under the ISET program funded by Employment and Social Development Canada (ESDC). My consent extends to providing my Social Insurance Number (SIN), to determine my eligibility for interventions such as skills training and wage subsidies as part of the Labour Market Development Agreements (LMDA) program.\", \"fr\": \"En poursuivant, je donne mon consentement explicite et informé à l\'Association des femmes autochtones du Canada et/ou ses titulaires de sous-conventions de l\'Programme d\'emploi et de développement des compétences autochtones (ici désigné par ISET), pour collecter des informations personnelles ou sensibles au titre de ma demande de financement du programme ISET financé par Employment and Social Development Canada (ESDC). Mon consentement s\'étend à la fourniture de mon numéro de sécurité sociale (SIN), pour déterminer ma qualification à des interventions telles que la formation en compétences et les subventions salariales dans le cadre du Programme d\'accords sur le développement du marché du travail (LMDA).\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-3\", \"text\": {\"en\": \"I acknowledge that the information is collected and administered in accordance with the Privacy Act (R.S.C. 1985, c P-21), the Department Employment and Social Development Canada Act (S.C. 2005, c.34), and the Access to Information Act (R.S.C., 1985, c.A-1). Information collected is to be used to determine eligibility for the ISET program; to measure results of this Agreement and evaluate its success; evaluate the effectiveness of the Program in achieving its objective; and, to meet its obligations of accountability by reporting on the results of the Program.\", \"fr\": \"Je reconnais que l\'information est collectée et gérée en vertu de la Loi sur la vie privée (R.S.C. 1985, c P-21), de la Loi sur le ministère de l\'emploi et du développement social du Canada (S.C. 2005, c.34), et de la Loi sur l\'accès à l\'information (R.S.C., 1985, c.A-1). L\'information est destinée à déterminer la qualification à ISET; à mesurer les résultats de ce contrat et à évaluer son succès; évaluer l\'efficacité du Programme dans atteinte de son objectif; et, à satisfaire ses obligations d\'accountabilité en rapportant les résultats du Programme.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-4\", \"text\": {\"en\": \"All information referred to above shall be treated as confidential, and the Native Women’s Association of Canada and its sub-agreement holders will take all security measures reasonably necessary for the protection of such information against unauthorized release or disclosure.\", \"fr\": \"Toute information mentionnée ci-dessus sera traitée comme confidentielle, et l\'Association des femmes autochtones du Canada et ses titulaires de sous-conventions prendront toutes mesures de sécurité raisonnables nécessaires pour la protection de cette information contre une divulgation ou une révélation non autorisée.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"consent\", \"hint\": {\"en\": \"I confirm that I have read and understood the above consent and agree to proceed with my application.\", \"fr\": \"Je confirme avoir lu et compris le consentement ci-dessus et j\'accepte de poursuivre ma demande.\"}, \"type\": \"signature-ack\", \"label\": {\"en\": \"Consent\", \"fr\": \"Signer avant de procéder\"}, \"required\": true, \"normalize\": \"none\", \"boxPadding\": \"m\", \"clearLabel\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"consent\", \"actionLabel\": {\"en\": \"Sign Now\", \"fr\": \"Signer Maintenant\"}, \"placeholder\": {\"en\": \"First Name Last Name\", \"fr\": \"Prénom Nom\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"en\": \"Signed\", \"fr\": \"Signé\"}, \"statusUnsignedText\": {\"en\": \"Unsigned\", \"fr\": \"Non signé\"}}], \"nextStepId\": \"indigenous-declaration\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Indigenous Declaration\", \"fr\": \"Indigenous Declaration\"}, \"stepId\": \"indigenous-declaration\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Indigenous Declaration\", \"fr\": \"La déclaration des Autochtones\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"By proceeding, I understand that the funding opportunity for which I am being considered is intended to increase Indigenous participation in the Canadian labour market and support First Nations, Metis and Inuit peoples’ access to sustainable and meaningful employment; and, provides access to training and employment supports to all Indigenous women in all their gender diversity, in Canada including status and non-status First Nations, Metis and Inuit peoples whether residing on or off-reserve, in urban centres and in rural, remote communities.\", \"fr\": \"En poursuivant, je comprends que l\'opportunité de financement pour laquelle je suis en considération vise à augmenter la participation des Autochtones au marché du travail canadien et à apporter des accès aux emplois et à des appuis d\'emploi durables et significatifs aux peuples Autochtones en Amérique du Nord, soit les Premières Nations, les Métis et les Inuit ; et, offre des accès à la formation et aux appuis d\'emploi à toutes les femmes autochtones de toutes leurs diversités de genre, dans toute l\'Amérique du Nord, y compris les Premières Nations, les Métis et les Inuit de statut et non-statut, qu\'elles résident sur ou hors réserve, dans des centres urbains et rurales, éloignées.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-3\", \"text\": {\"en\": \"Further, I understand that providing false or misleading information and/or omission of information by me about my Indigenous identity may result in an investigation and if the investigation is founded, will be grounds for immediate suspension of any funding and further, revocation of any Funding Agreement between me and the Native Women’s Association of Canada and/or its sub-agreement holders, and will result in a repayment of funds to Employment and Social Development Canada (ESDC), for monies I received to which I was not entitled.\", \"fr\": \"De plus, je comprends que la fourniture d\'informations fausses ou trompeuses et/ou l\'omission d\'informations par moi concernant ma identité autochtone peut entraîner une enquête et si l\'enquête est confirmée, sera les raisons d\'une suspension immédiate de toute subvention et de plus, de l\'annulation d\'un Accord de financement entre moi et l\'Association des Femmes Autochtones du Canada et/ou ses titulaires de sous-accords, et causera un remboursement de fonds à l\'Emploi et au Développement Social du Canada (ESDC), pour des monnaies dont je n\'étais pas éligible.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"indigenous-declaration\", \"hint\": {\"en\": \"I declare that I am an Indigenous person according to the following definition: Indigenous Peoples are people who are First Nations, Inuit or Métis.\", \"fr\": \"I declare that I am an Indigenous person according to the following definition: Indigenous Peoples are people who are First Nations, Inuit or Métis.\"}, \"type\": \"signature-ack\", \"label\": {\"en\": \"Declaration\", \"fr\": \"Declaration\"}, \"required\": true, \"normalize\": \"none\", \"boxPadding\": \"m\", \"clearLabel\": {\"en\": \"Clear\", \"fr\": \"Clear\"}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"indigenous_declaration\", \"actionLabel\": {\"en\": \"Sign Now\", \"fr\": \"Sign Now\"}, \"placeholder\": {\"en\": \"First Last\", \"fr\": \"First Last\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"en\": \"Signed\", \"fr\": \"Signed\"}, \"statusUnsignedText\": {\"en\": \"Not signed\", \"fr\": \"Not signed\"}}], \"nextStepId\": \"eligibility\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Eligibility\", \"fr\": \"Eligibility\"}, \"stepId\": \"eligibility\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Eligibility Check\", \"fr\": \"Vérification de l\'éligibilité\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"Please answer the following questions to determine your eligibility for the ISET program.\", \"fr\": \"Répondez aux questions suivantes pour déterminer votre éligibilité au programme ISET.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body-l\"}, {\"id\": \"eligibility-indigenous\", \"hint\": {\"en\": \"This program is for Indigenous Peoples: First Nations, Inuit, or Métis.\", \"fr\": \"Ce programme est destiné aux Peuples autochtones : First Nations, Inuit ou Métis.\"}, \"name\": \"eligibility-indigenous\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Are you a member of a First Nations, Inuit, or Métis group?\", \"fr\": \"Êtes-vous un membre d\'un groupe First Nations, Inuit ou Métis ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-indigenous\", \"validation\": {\"rules\": [{\"id\": \"eligibility-indigenous-required\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-indigenous\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"eligibility-female\", \"hint\": {\"en\": \"ISET is open to Indigenous women, trans women, Two-Spirit, and gender-diverse people who identify as women.\", \"fr\": \"ISET est ouvert aux femmes autochtones, aux trans femmes, aux personnes de l\'identité deux-esprits et aux personnes transgenres qui s\'identifient comme des femmes.\"}, \"name\": \"eligibility-female\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Do you identify as a woman, trans woman, Two-Spirit, or gender-diverse individual who identifies as a woman?\", \"fr\": \"Identifiez-vous-vous comme une femme, une trans femme, de l\'identité deux-esprits ou une personne transgenre qui s\'identifie comme une femme ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-female\", \"validation\": {\"rules\": [{\"id\": \"rule-1756933101438-0dxf\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-female\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}