", \"spellcheck\": true, \"storageKey\": \"income-other\"}, {\"id\": \"income-other-description\", \"type\": \"input\", \"class\": \"govuk-input\", \"label\": {\"en\": \"Other Income\", \"fr\": \"Other Income\"}, \"prefix\": {\"text\": \"$\"}, \"suffix\": {\"text\": \"per month\"}, \"required\": false, \"inputMode\": \"numeric\", \"inputType\": \"text\", \"normalize\": \"trim\", \"labelClass\": \"govuk-label--s\", \"spellcheck\": true, \"storageKey\": \"income-other-description\"}], \"nextStepId\": \"household-expenses\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Household Expenses\", \"fr\": \"Household Expenses\"}, \"stepId\": \"household-expenses\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Household Expenses\", \"fr\": \"Exemple de texte\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"Please disclose all sources of monthly household income. Documentation and proof of financial situation is required prior to any approval of funding.\", \"fr\": \"Exemple de texte\"}, \"type\": \"paragraph\", \"class\": \"govuk-body-l\"}, {\"id\": \"expenses-rent\", \"type\": \"input\", \"class\": \"govuk-input\", \"label\": {\"en\": \"Rent/Mortgage\", \"fr\": \"Rent/Mortgage\"}, \"prefix\": {\"text\": \"$\"}, \"suffix\": {\"text\": \"per month\"}, \"required\": false, \"inputMode\": \"numeric\", \"inputType\": \"text\", \"normalize\": \"trim\", \"labelClass\": \"govuk-label--s\", \"spellcheck\": false, \"storageKey\": \"expenses-rent\"}, {\"id\": \"expenses-utilities\", \"type\": \"input\", \"class\": \"govuk-input\", \"label\": {\"en\": \"Utilities (Hydro, water, natural gas, sewer, garbage, internet)\", \"fr\": \"Utilities (Hydro, water, natural gas, sewer, garbage, internet)\"}, \"prefix\": {\"text\": \"$\"}, \"suffix\": {\"text\": \"per month\"}, \"required\": false, \"inputType\": \"text\", \"normalize\": \"trim\", \"labelClass\": \"govuk-label--s\", \"spellcheck\": true, \"storageKey\": \"expenses-utilities\"}, {\"id\": \"expenses-groceries\", \"type\": \"input\", \"class\": \"govuk-input\", \"label\": {\"en\": \"Groceries\", \"fr\": \"Groceries\"}, \"prefix\": {\"text\": \"$\"}, \"suffix\": {\"text\": \"per month\"}, \"required\": false, \"inputType\": \"text\", \"normalize\": \"trim\", \"labelClass\": \"govuk-label--s\", \"spellcheck\": true, \"storageKey\": \"expenses-groceries\"}, {\"id\": \"expenses-transitpass\", \"type\": \"input\", \"class\": \"govuk-input\", \"label\": {\"en\": \"Transit Pass\", \"fr\": \"Transit Pass\"}, \"prefix\": {\"text\": \"$\"}, \"suffix\": {\"text\": \"per month\"}, \"required\": false, \"inputType\": \"text\", \"normalize\": \"trim\", \"labelClass\": \"govuk-label--s\", \"spellcheck\": true, \"storageKey\": \"expenses-transitpass\"}, {\"id\": \"expenses-other-list\", \"hint\": {\"en\": \"If you have other expenses, list them here.\", \"fr\": \"N\'incluez pas d\'informations personnelles ou financières.\"}, \"type\": \"textarea\", \"class\": \"govuk-textarea\", \"label\": {\"en\": \"Other Expenses\", \"fr\": \"Champ multi-lignes\"}, \"required\": false, \"normalize\": \"trim\", \"labelClass\": \"govuk-label--s\", \"storageKey\": \"expenses-other-list\"}, {\"id\": \"example-input-5\", \"hint\": {\"en\": \"Please enter a total for the listed other expenses\", \"fr\": \"Please enter a total for the listed other expenses\"}, \"type\": \"input\", \"class\": \"govuk-input\", \"label\": {\"en\": \"Other Expenses\", \"fr\": \"Other Expenses\"}, \"prefix\": {\"text\": \"$\"}, \"suffix\": {\"text\": \"per month\"}, \"required\": false, \"inputType\": \"text\", \"normalize\": \"trim\", \"labelClass\": \"govuk-label--s\", \"spellcheck\": true, \"storageKey\": \"example-input-5\"}], \"nextStepId\": \"summary-page\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Summary Page\", \"fr\": \"Summary Page\"}, \"stepId\": \"summary-page\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Review your application\", \"fr\": \"Passez en revue votre demande\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-m\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"This is the data you have entered.  Please take some time to review it and esure it is complete and accurate.\", \"fr\": \"Voici les données que vous avez saisies. Veuillez prendre un moment pour les revoir et vous assurer qu\'elles sont complètes et exactes.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body-l\"}, {\"id\": \"summary-list-2\", \"rows\": [{\"key\": \"social-insurance-number\", \"label\": {\"en\": \"What is your Social Insurance Number (SIN)?\", \"fr\": \"Quel est votre numéro d\'assurance sociale (SIN) ?\"}}, {\"key\": \"first-name\", \"label\": {\"en\": \"First Name\", \"fr\": \"Premier Nom\"}}, {\"key\": \"last-name\", \"label\": {\"en\": \"Last Name\", \"fr\": \"Nom de Famille\"}}, {\"key\": \"middle-names\", \"label\": {\"en\": \"Middle Name(s)\", \"fr\": \"Nom de milieu(s)\"}}, {\"key\": \"preferred-name\", \"label\": {\"en\": \"Preferred Name (if different)\", \"fr\": \"Nom préféré (si différent)\"}}, {\"key\": \"dob\", \"label\": {\"en\": \"What is your date of birth?\", \"fr\": \"Entrez la date\"}}, {\"key\": \"eligibility-indigenous\", \"label\": {\"en\": \"What is your gender identity?\", \"fr\": \"What is your gender identity?\"}, \"originalKey\": \"example-radio\"}, {\"key\": \"visible-minority\", \"label\": {\"en\": \"Visible Minority?\", \"fr\": \"Visible Minority?\"}}, {\"key\": \"marital-status\", \"label\": {\"en\": \"Marital Status\", \"fr\": \"Marital Status\"}}, {\"key\": \"spouses-name\", \"label\": {\"en\": \"Spouse\'s Name\", \"fr\": \"Spouse\'s Name\"}}, {\"key\": \"dependent-children\", \"label\": {\"en\": \"Do you have dependent children?\", \"fr\": \"Do you have dependent children?\"}}, {\"key\": \"ages-of-children\", \"label\": {\"en\": \"Ages of Children\", \"fr\": \"Ages of Children\"}}, {\"key\": \"has-disability\", \"label\": {\"en\": \"Do you consider yourself to have a disability?\", \"fr\": \"Est-ce que vous considérez avoir un handicap ?\"}}, {\"key\": \"social-assistance\", \"label\": {\"en\": \"Are you currently receiving social assistance?\", \"fr\": \"Est-ce que vous recevez actuellement de l\'aide sociale ?\"}}, {\"key\": \"top-up-amount\", \"label\": {\"en\": \"what is your allowable top-up amount (if applicable)\", \"fr\": \"Quelle est votre montant d\'allowance maximale (si applicable)\"}}, {\"key\": \"labour-force-status\", \"label\": {\"en\": \"What is your current labour force status?\", \"fr\": \"What is your current labour force status?\"}}, {\"key\": \"eligibility-female\", \"label\": {\"en\": \"What highest level of education did you complete?\", \"fr\": \"What highest level of education did you complete?\"}, \"originalKey\": \"example-radio-2\"}, {\"key\": \"education-year\", \"label\": {\"en\": \"Year you completed your highest level of education\", \"fr\": \"Year you completed your highest level of education\"}}, {\"key\": \"edication-location\", \"label\": {\"en\": \"Province, territory or country where you completed your highest level of education\", \"fr\": \"Province, territory or country where you completed your highest level of education\"}}], \"type\": \"summary-list\", \"hideEmpty\": true, \"emptyFallback\": {\"en\": \"Not provided\", \"fr\": \"Non fourni\"}}, {\"id\": \"summary-list-3\", \"rows\": [{\"key\": \"address-street-address\", \"label\": {\"en\": \"Street Address\", \"fr\": \"Street Address\"}, \"originalKey\": \"street-address\"}, {\"key\": \"address-city\", \"label\": {\"en\": \"City\", \"fr\": \"City\"}}, {\"key\": \"address-postcode\", \"label\": {\"en\": \"Postal Code\", \"fr\": \"Postal Code\"}}, {\"key\": \"address-mailing-address\", \"label\": {\"en\": \"Mailing Address (if different)\", \"fr\": \"Champ multi-lignes\"}}, {\"key\": \"telephone-day\", \"label\": {\"en\": \"Daytime Phone Number\", \"fr\": \"Daytime Phone Number\"}}, {\"key\": \"telephone-alt\", \"label\": {\"en\": \"Alternative Phone Number (optional)\", \"fr\": \"Alternative Phone Number (optional)\"}, \"originalKey\": \"example-input-5\"}, {\"key\": \"contact-email-address\", \"label\": {\"en\": \"Email Address\", \"fr\": \"Email Address\"}, \"originalKey\": \"example-input-6\"}, {\"key\": \"example-select\", \"label\": {\"en\": \"Province or Territory\", \"fr\": \"Province or Territory\"}}, {\"key\": \"telephone-alt\", \"label\": {\"en\": \"Alternative Phone Number (optional)\", \"fr\": \"Alternative Phone Number (optional)\"}}, {\"key\": \"emergency-contact-name\", \"label\": {\"en\": \"Emergency Contact Name\", \"fr\": \"Emergency Contact Name\"}}, {\"key\": \"emergency-contact-telephone\", \"label\": {\"en\": \"Emergency Contact Phone Number\", \"fr\": \"Emergency Contact Phone Number\"}}, {\"key\": \"emergency-contact-relationship\", \"label\": {\"en\": \"Relationship to You\", \"fr\": \"Relationship to You\"}}], \"type\": \"summary-list\", \"hideEmpty\": true, \"emptyFallback\": {\"en\": \"Not provided\", \"fr\": \"Non fourni\"}}, {\"id\": \"summary-list-4\", \"rows\": [{\"key\": \"eligibility-indigenous\", \"label\": {\"en\": \"What is your gender identity?\", \"fr\": \"What is your gender identity?\"}, \"originalKey\": \"example-radio\"}, {\"key\": \"registration-number\", \"label\": {\"en\": \"What is your registration number?\", \"fr\": \"What is your registration number?\"}}, {\"key\": \"home-comminuty\", \"label\": {\"en\": \"What is your home community?\", \"fr\": \"What is your home community?\"}}], \"type\": \"summary-list\", \"hideEmpty\": true, \"emptyFallback\": {\"en\": \"Not provided\", \"fr\": \"Non fourni\"}}, {\"id\": \"summary-list-5\", \"rows\": [{\"key\": \"barriers\", \"label\": {\"en\": \"What barriers are you currently facing?\", \"fr\": \"What barriers are you currently facing?\"}}, {\"key\": \"other-barrier\", \"label\": {\"en\": \"Other barrier (please specify)\", \"fr\": \"Other barrier (please specify)\"}}, {\"key\": \"target-program\", \"label\": {\"en\": \"Have you already identified a training program or employer?\", \"fr\": \"Have you already identified a training program or employer?\"}}, {\"key\": \"requested-supports\", \"label\": {\"en\": \"Which of the following supports are you requesting?\", \"fr\": \"Which of the following supports are you requesting?\"}}, {\"key\": \"other-requested-support\", \"label\": {\"en\": \"Other support (please specify)\", \"fr\": \"Other support (please specify)\"}}], \"type\": \"summary-list\", \"hideEmpty\": true, \"emptyFallback\": {\"en\": \"Not provided\", \"fr\": \"Non fourni\"}}, {\"id\": \"summary-list-6\", \"rows\": [{\"key\": \"income-employment\", \"label\": {\"en\": \"Employment Income\", \"fr\": \"Employment Income\"}}, {\"key\": \"income-spousal\", \"label\": {\"en\": \"Spousal Income\", \"fr\": \"Spousal Income\"}}, {\"key\": \"income-social-assist\", \"label\": {\"en\": \"Social Assistance\", \"fr\": \"Social Assistance\"}}, {\"key\": \"income-child-benefit\", \"label\": {\"en\": \"Child Tax Benefit\", \"fr\": \"Child Tax Benefit\"}}, {\"key\": \"income-jordans\", \"label\": {\"en\": \"Jordan’s Principle\", \"fr\": \"Jordan’s Principle\"}}, {\"key\": \"income-band-funding\", \"label\": {\"en\": \"Band Funding\", \"fr\": \"Band Funding\"}}, {\"key\": \"income-other\", \"label\": {\"en\": \"Other Income (if applicable)\", \"fr\": \"Other Income (if applicable)\"}}, {\"key\": \"income-other-description\", \"label\": {\"en\": \"Other Income\", \"fr\": \"Other Income\"}}], \"type\": \"summary-list\", \"hideEmpty\": true, \"emptyFallback\": {\"en\": \"Not provided\", \"fr\": \"Non fourni\"}}, {\"id\": \"summary-list-7\", \"rows\": [{\"key\": \"expenses-rent\", \"label\": {\"en\": \"Rent/Mortgage\", \"fr\": \"Rent/Mortgage\"}}, {\"key\": \"expenses-utilities\", \"label\": {\"en\": \"Utilities (Hydro, water, natural gas, sewer, garbage, internet)\", \"fr\": \"Utilities (Hydro, water, natural gas, sewer, garbage, internet)\"}}, {\"key\": \"expenses-groceries\", \"label\": {\"en\": \"Groceries\", \"fr\": \"Groceries\"}}, {\"key\": \"expenses-transitpass\", \"label\": {\"en\": \"Transit Pass\", \"fr\": \"Transit Pass\"}}, {\"key\": \"expenses-other-list\", \"label\": {\"en\": \"Other Expenses\", \"fr\": \"Champ multi-lignes\"}}, {\"key\": \"telephone-alt\", \"label\": {\"en\": \"Other Expenses\", \"fr\": \"Other Expenses\"}, \"originalKey\": \"example-input-5\"}], \"type\": \"summary-list\", \"hideEmpty\": true, \"emptyFallback\": {\"en\": \"Not provided\", \"fr\": \"Non fourni\"}}], \"nextStepId\": \"iset-document-upload\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"ISET Document Upload\", \"fr\": \"ISET Document Upload\"}, \"stepId\": \"iset-document-upload\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Document Upload\", \"fr\": \"Téléchargement de document\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"Based on your answers the following documents must be submitted in support of your application.\", \"fr\": \"Sur la base de vos réponses, les documents suivants doivent être soumis à l\'appui de votre demande.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body-l\"}, {\"id\": \"status-card\", \"hint\": {\"en\": \"Always required; base identity/eligibility proof\", \"fr\": \"Toujours requis; preuve d\'identité/éligibilité de base\"}, \"type\": \"file-upload\", \"label\": {\"en\": \"Status/Treaty Card (or equivalent)\", \"fr\": \"Statut/Carte de traité (ou équivalent)\"}, \"accept\": \".pdf,.jpg,.jpeg,.png,.gif,.heic\", \"disabled\": false, \"multiple\": false, \"required\": false, \"maxSizeMb\": 1, \"normalize\": \"none\", \"labelClass\": \"govuk-label--m\", \"storageKey\": \"status-card\", \"showMaxSize\": true, \"showMimeList\": false}, {\"id\": \"govt-id\", \"hint\": {\"en\": \"Always required as a secondary identity document\", \"fr\": \"Toujours requis comme document d\'identité secondaire\"}, \"type\": \"file-upload\", \"label\": {\"en\": \"Government-Issued ID\", \"fr\": \"Pièce d\'identité délivrée par le gouvernement\"}, \"accept\": \".pdf,.jpg,.jpeg,.png,.gif,.heic\", \"disabled\": false, \"multiple\": false, \"required\": false, \"maxSizeMb\": 1, \"normalize\": \"none\", \"labelClass\": \"govuk-label--m\", \"storageKey\": \"govt-id\", \"showMaxSize\": true, \"showMimeList\": false}, {\"id\": \"acceptance-letter\", \"hint\": {\"en\": \"You indicated that you have been accepted into a skills development or training program.  Please upload you letter of acceptance into that program.\", \"fr\": \"Vous avez indiqué que vous avez été accepté dans un programme de développement des compétences ou de formation. Veuillez télécharger votre lettre d\'acceptation dans ce programme.\"}, \"type\": \"file-upload\", \"label\": {\"en\": \"Letter of Acceptance\", \"fr\": \"Lettre d\'acceptation\"}, \"accept\": \".pdf,.jpg,.jpeg,.png,.gif,.heic\", \"disabled\": false, \"multiple\": false, \"required\": false, \"maxSizeMb\": 3, \"normalize\": \"none\", \"conditions\": {\"all\": [{\"op\": \"equals\", \"ref\": \"target-program\", \"value\": \"Yes\"}, {\"op\": \"equals\", \"ref\": \"target-program\", \"value\": \"skills_development\"}]}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"acceptance-letter\", \"showMaxSize\": true, \"showMimeList\": false}, {\"id\": \"applicant-pay-stubs\", \"hint\": {\"en\": \"You indicated that you have a salaried income.  Please upload your last three-months\' pay stubs.\", \"fr\": \"Vous avez indiqué que vous avez un revenu salarial. Veuillez télécharger vos trois derniers bulletins de paie.\"}, \"type\": \"file-upload\", \"label\": {\"en\": \"Pay Stubs (Applicant)\", \"fr\": \"Bulletins de paie (demandeur)\"}, \"accept\": \".pdf,.jpg,.jpeg,.png,.gif,.heic\", \"disabled\": false, \"multiple\": true, \"required\": false, \"maxSizeMb\": 6, \"normalize\": \"none\", \"conditions\": {\"all\": [{\"op\": \">\", \"ref\": \"income-employment\", \"value\": \"0\"}]}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"applicant-pay-stubs\", \"showMaxSize\": true, \"showMimeList\": false}, {\"id\": \"spouse-pay-stubs\", \"hint\": {\"en\": \"You indicated that you are married, and that your spouse has an income.  Please upload your spouse\'s last three-months\' pay stubs.\", \"fr\": \"Vous avez indiqué que vous êtes marié et que votre conjoint a un revenu. Veuillez télécharger les trois derniers bulletins de paie de votre conjoint.\"}, \"type\": \"file-upload\", \"label\": {\"en\": \"Pay Stubs (Spouse)\", \"fr\": \"Bulletins de paie (conjoint)\"}, \"accept\": \".pdf,.jpg,.jpeg,.png,.gif,.heic\", \"disabled\": false, \"multiple\": true, \"required\": false, \"maxSizeMb\": 6, \"normalize\": \"none\", \"conditions\": {\"all\": [{\"op\": \"equals\", \"ref\": \"marital-status\", \"value\": \"married\"}, {\"op\": \">\", \"ref\": \"income-spousal\", \"value\": \"0\"}]}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"spouse-pay-stubs\", \"showMaxSize\": true, \"showMimeList\": false}, {\"id\": \"uploaded-file-6\", \"hint\": {\"en\": \"You indicated that you have recieved no bank funding in relation to this application.  Please upload the letter denying you band funding.\", \"fr\": \"Vous avez indiqué que vous n\'avez reçu aucun financement bancaire en relation avec cette demande. Veuillez télécharger la lettre de refus de financement de la bande.\"}, \"type\": \"file-upload\", \"label\": {\"en\": \"Band Denial Letter\", \"fr\": \"Lettre de refus de la bande\"}, \"accept\": \".pdf,.jpg,.jpeg,.png,.gif,.heic\", \"disabled\": false, \"multiple\": false, \"required\": false, \"maxSizeMb\": 3, \"normalize\": \"none\", \"conditions\": {\"all\": [{\"op\": \"notExists\", \"ref\": \"income-band-funding\"}]}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"uploaded-file-6\", \"showMaxSize\": true, \"showMimeList\": false}], \"nextStepId\": \"legal-and-submission\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Legal and Submission\", \"fr\": \"Legal and Submission\"}, \"stepId\": \"legal-and-submission\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Submission\", \"fr\": \"Soumission\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"You are now ready to submit your application. Please read the following legal declaration carfully and indicate that your acceptance with a signature below.   When you hit submit the application will be sent to NWAC and you will recieve a confimation email detailing next steps.   You can sign back into your dashbaord to check status and contact the case-workers.\", \"fr\": \"Vous êtes maintenant prêt à soumettre votre demande. Veuillez lire attentivement la déclaration légale suivante et indiquer votre acceptation par une signature ci-dessous. Lorsque vous appuierez sur soumettre, la demande sera envoyée à l\'ANFNC et vous recevrez un courriel de confirmation détaillant les prochaines étapes. Vous pouvez vous reconnecter à votre tableau de bord pour vérifier le statut et contacter les intervenants.\"}, \"type\": \"paragraph\", \"class\": \"govuk-hint\"}, {\"id\": \"paragraph-3\", \"text\": {\"en\": \"I, the undersigned, give my expressed and informed consent to the Native Women’s Association of Canada and/or its sub-agreement holders to the Indigenous Skills and Employment Training Program (hereinafter referred to as ISET), to collect personal or sensitive information as it relates to my request for funding under the ISET program funded by Employment and Social Development Canada (ESDC). My consent extends to providing my Social Insurance Number (SIN), to determine my eligibility for interventions such as skills training and wage subsidies as part of the Labour Market Development Agreements (LMDA) program.\", \"fr\": \"Je, le soussigné, donne mon consentement exprimé et éclairé à l’Association des femmes autochtones du Canada et/ou à ses titulaires de sous-accords du Programme de formation et de perfectionnement des compétences autochtones (ci-après dénommé ISET), pour recueillir des renseignements personnels ou sensibles en lien avec ma demande de financement dans le cadre du programme ISET financé par Emploi et Développement social Canada (EDSC). Mon consentement s’étend à la fourniture de mon numéro d’assurance sociale (NAS), afin de déterminer mon admissibilité à des interventions telles que la formation professionnelle et les subventions salariales dans le cadre du programme des ententes de développement du marché du travail (EDMT).\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-4\", \"text\": {\"en\": \"I acknowledge that the information is collected and administered in accordance with the Privacy Act (R.S.C. 1985, c P-21), the Department Employment and Social Development Canada Act (S.C. 2005, c.34), and the Access to Information Act (R.S.C., 1985, c.A-1). Information collected is to be used to determine eligibility for the ISET program; to measure results of this Agreement and evaluate its success; evaluate the effectiveness of the Program in achieving its objective; and, to meet its obligations of accountability by reporting on the results of the Program.\", \"fr\": \"Je reconnais que les renseignements sont recueillis et administrés conformément à la Loi sur la protection des renseignements personnels (L.R.C. 1985, ch. P-21), la Loi sur le ministère de l’Emploi et du Développement social Canada (L.C. 2005, ch. 34) et la Loi sur l’accès à l’information (L.R.C., 1985, ch. A-1). Les renseignements recueillis serviront à déterminer l’admissibilité au programme ISET; à mesurer les résultats de la présente entente et à en évaluer le succès; à évaluer l’efficacité du programme dans l’atteinte de ses objectifs; et à remplir ses obligations de reddition de comptes en faisant rapport des résultats du programme.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-5\", \"text\": {\"en\": \"All information referred to above shall be treated as confidential, and the Native Women’s Association of Canada and its sub-agreement holders will take all security measures reasonably necessary for the protection of such information against unauthorized release or disclosure.\", \"fr\": \"Tous les renseignements mentionnés ci-dessus seront traités de manière confidentielle, et l’Association des femmes autochtones du Canada ainsi que ses titulaires de sous-accords prendront toutes les mesures de sécurité raisonnablement nécessaires pour protéger ces renseignements contre toute diffusion ou divulgation non autorisée.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-6\", \"text\": {\"en\": \"I understand that my personal information shall not be used or disclosed for purposes other than those for which it was collected, except with the expressed consent of you, as the client, or as required by law. Personal information shall be retained only as long as necessary for the fulfilment of those purposes.\", \"fr\": \"Je comprends que mes renseignements personnels ne seront pas utilisés ou divulgués à d’autres fins que celles pour lesquelles ils ont été recueillis, sauf avec mon consentement exprès, en tant que client, ou si la loi l’exige. Les renseignements personnels ne seront conservés que pour la durée nécessaire à la réalisation de ces fins.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-7\", \"text\": {\"en\": \"I understand that the funding opportunity for which I am being considered is intended to increase Indigenous participation in the Canadian labour market and support First Nations, Metis and Inuit peoples’ access to sustainable and meaningful employment; and, provides access to training and employment supports to all Indigenous women in all their gender diversity, in Canada including status and non-status First Nations, Metis and Inuit peoples whether residing on or off-reserve, in urban centres and in rural, remote communities.\", \"fr\": \"Je comprends que l’occasion de financement pour laquelle je suis considéré vise à accroître la participation des Autochtones au marché du travail canadien et à soutenir l’accès des Premières Nations, des Métis et des Inuits à un emploi durable et significatif; et qu’elle offre un accès à la formation et aux soutiens à l’emploi à toutes les femmes autochtones dans toute leur diversité de genre, au Canada, y compris les membres des Premières Nations avec ou sans statut, les Métis et les Inuits, qu’elles résident dans des réserves, des centres urbains ou des collectivités rurales et éloignées.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-8\", \"text\": {\"en\": \"I understand that providing false or misleading information and/or omission of information by me about my Indigenous identity may result in an investigation and if the investigation is founded, will be grounds for immediate suspension of any funding and further, revocation of any Funding Agreement between me and the Native Women’s Association of Canada and/or its sub-agreement holders, and will result in a repayment of funds to Employment and Social Development Canada (ESDC), for monies I received to which I was not entitled.\", \"fr\": \"Je comprends que la fourniture de renseignements faux ou trompeurs et/ou l’omission de renseignements par moi concernant mon identité autochtone peut entraîner une enquête et, si l’enquête est fondée, constitueront un motif de suspension immédiate de tout financement et, de plus, de révocation de toute entente de financement entre moi et l’Association des femmes autochtones du Canada et/ou ses titulaires de sous-accords, et entraîneront le remboursement des fonds à Emploi et Développement social Canada (EDSC), pour les montants que j’ai reçus et auxquels je n’avais pas droit.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-9\", \"text\": {\"en\": \"I declare that I am an Indigenous person according to the following definition: Indigenous Peoples are people who are First Nations, Inuit or Métis.\", \"fr\": \"Je déclare que je suis une personne autochtone selon la définition suivante : Les peuples autochtones sont les personnes qui sont Premières Nations, Inuits ou Métis.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"applicant-signature\", \"hint\": {\"en\": \"Enter your full legal name then press Sign.\", \"fr\": \"Entrez votre nom légal complet, puis appuyez sur Signer.\"}, \"type\": \"signature-ack\", \"label\": {\"en\": \"Type your full name to sign\", \"fr\": \"Tapez votre nom complet pour signer\"}, \"required\": true, \"normalize\": \"none\", \"boxPadding\": \"m\", \"clearLabel\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"applicant_signature\", \"actionLabel\": {\"en\": \"Sign Now\", \"fr\": \"Signer maintenant\"}, \"placeholder\": {\"en\": \"First Last\", \"fr\": \"Prénom Nom\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"en\": \"Signed\", \"fr\": \"Signé\"}, \"statusUnsignedText\": {\"en\": \"Not signed\", \"fr\": \"Non signé\"}}], \"description\": {\"en\": \"\", \"fr\": \"\"}}], \"version\": \"2025-10-17T18:28:24.909Z#21\", \"checksum\": \"4a01019b285ec034bf9cd6587cea8842a81a6ae4b277ede4c588ae7981821ead\", \"publishedAt\": \"2025-10-17T18:28:24.909Z\", \"publishedBy\": {\"id\": null, \"name\": null, \"email\": null}, \"schemaEnvelope\": {\"raw\": {\"usedTemplateIds\": {}}, \"meta\": {\"counts\": {\"steps\": 22, \"components\": 114}, \"workflow\": {\"id\": 21, \"name\": \"ISET Intake Testing\", \"status\": \"active\"}, \"templates\": [{\"id\": 29, \"type\": \"paragraph\", \"count\": 42, \"version\": 1, \"template_key\": \"text-block\"}, {\"id\": 35, \"type\": \"signature-ack\", \"count\": 3, \"version\": 1, \"template_key\": \"signature-ack\"}, {\"id\": 1, \"type\": \"radio\", \"count\": 19, \"version\": 1, \"template_key\": \"radio\"}, {\"id\": 26, \"type\": \"input\", \"count\": 36, \"version\": 1, \"template_key\": \"input\"}, {\"id\": 13, \"type\": \"date-input\", \"count\": 1, \"version\": 1, \"template_key\": \"date-input\"}, {\"id\": 2, \"type\": \"select\", \"count\": 1, \"version\": 1, \"template_key\": \"select\"}, {\"id\": 32, \"type\": \"textarea\", \"count\": 2, \"version\": 1, \"template_key\": \"textarea\"}, {\"id\": 31, \"type\": \"character-count\", \"count\": 2, \"version\": 1, \"template_key\": \"character-count\"}, {\"id\": 33, \"type\": \"checkbox\", \"count\": 2, \"version\": 1, \"template_key\": \"checkbox\"}, {\"id\": 24, \"type\": \"summary-list\", \"count\": 6, \"version\": 1, \"template_key\": \"summary-list\"}, {\"id\": 19, \"type\": \"file-upload\", \"count\": 6, \"version\": 1, \"template_key\": \"file-upload\"}], \"generatedAt\": \"2025-10-17T18:28:24.907Z\", \"schemaVersion\": \"1.1\"}, \"steps\": [{\"type\": \"schema\", \"title\": {\"en\": \"Consent\", \"fr\": \"Consent\"}, \"stepId\": \"consent\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Consent Form\", \"fr\": \"Formulaire de consentement\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"By proceeding, I give my expressed and informed consent to the Native Women’s Association of Canada and/or its sub-agreement holders to the Indigenous Skills and Employment Training Program (hereinafter referred to as ISET), to collect personal or sensitive information as it relates to my request for funding under the ISET program funded by Employment and Social Development Canada (ESDC). My consent extends to providing my Social Insurance Number (SIN), to determine my eligibility for interventions such as skills training and wage subsidies as part of the Labour Market Development Agreements (LMDA) program.\", \"fr\": \"En poursuivant, je donne mon consentement explicite et informé à l\'Association des femmes autochtones du Canada et/ou ses titulaires de sous-conventions de l\'Programme d\'emploi et de développement des compétences autochtones (ici désigné par ISET), pour collecter des informations personnelles ou sensibles au titre de ma demande de financement du programme ISET financé par Employment and Social Development Canada (ESDC). Mon consentement s\'étend à la fourniture de mon numéro de sécurité sociale (SIN), pour déterminer ma qualification à des interventions telles que la formation en compétences et les subventions salariales dans le cadre du Programme d\'accords sur le développement du marché du travail (LMDA).\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-3\", \"text\": {\"en\": \"I acknowledge that the information is collected and administered in accordance with the Privacy Act (R.S.C. 1985, c P-21), the Department Employment and Social Development Canada Act (S.C. 2005, c.34), and the Access to Information Act (R.S.C., 1985, c.A-1). Information collected is to be used to determine eligibility for the ISET program; to measure results of this Agreement and evaluate its success; evaluate the effectiveness of the Program in achieving its objective; and, to meet its obligations of accountability by reporting on the results of the Program.\", \"fr\": \"Je reconnais que l\'information est collectée et gérée en vertu de la Loi sur la vie privée (R.S.C. 1985, c P-21), de la Loi sur le ministère de l\'emploi et du développement social du Canada (S.C. 2005, c.34), et de la Loi sur l\'accès à l\'information (R.S.C., 1985, c.A-1). L\'information est destinée à déterminer la qualification à ISET; à mesurer les résultats de ce contrat et à évaluer son succès; évaluer l\'efficacité du Programme dans atteinte de son objectif; et, à satisfaire ses obligations d\'accountabilité en rapportant les résultats du Programme.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-4\", \"text\": {\"en\": \"All information referred to above shall be treated as confidential, and the Native Women’s Association of Canada and its sub-agreement holders will take all security measures reasonably necessary for the protection of such information against unauthorized release or disclosure.\", \"fr\": \"Toute information mentionnée ci-dessus sera traitée comme confidentielle, et l\'Association des femmes autochtones du Canada et ses titulaires de sous-conventions prendront toutes mesures de sécurité raisonnables nécessaires pour la protection de cette information contre une divulgation ou une révélation non autorisée.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"consent\", \"hint\": {\"en\": \"I confirm that I have read and understood the above consent and agree to proceed with my application.\", \"fr\": \"Je confirme avoir lu et compris le consentement ci-dessus et j\'accepte de poursuivre ma demande.\"}, \"type\": \"signature-ack\", \"label\": {\"en\": \"Consent\", \"fr\": \"Signer avant de procéder\"}, \"required\": true, \"normalize\": \"none\", \"boxPadding\": \"m\", \"clearLabel\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"consent\", \"actionLabel\": {\"en\": \"Sign Now\", \"fr\": \"Signer Maintenant\"}, \"placeholder\": {\"en\": \"First Name Last Name\", \"fr\": \"Prénom Nom\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"en\": \"Signed\", \"fr\": \"Signé\"}, \"statusUnsignedText\": {\"en\": \"Unsigned\", \"fr\": \"Non signé\"}}], \"nextStepId\": \"indigenous-declaration\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Indigenous Declaration\", \"fr\": \"Indigenous Declaration\"}, \"stepId\": \"indigenous-declaration\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Indigenous Declaration\", \"fr\": \"La déclaration des Autochtones\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"By proceeding, I understand that the funding opportunity for which I am being considered is intended to increase Indigenous participation in the Canadian labour market and support First Nations, Metis and Inuit peoples’ access to sustainable and meaningful employment; and, provides access to training and employment supports to all Indigenous women in all their gender diversity, in Canada including status and non-status First Nations, Metis and Inuit peoples whether residing on or off-reserve, in urban centres and in rural, remote communities.\", \"fr\": \"En poursuivant, je comprends que l\'opportunité de financement pour laquelle je suis en considération vise à augmenter la participation des Autochtones au marché du travail canadien et à apporter des accès aux emplois et à des appuis d\'emploi durables et significatifs aux peuples Autochtones en Amérique du Nord, soit les Premières Nations, les Métis et les Inuit ; et, offre des accès à la formation et aux appuis d\'emploi à toutes les femmes autochtones de toutes leurs diversités de genre, dans toute l\'Amérique du Nord, y compris les Premières Nations, les Métis et les Inuit de statut et non-statut, qu\'elles résident sur ou hors réserve, dans des centres urbains et rurales, éloignées.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"paragraph-3\", \"text\": {\"en\": \"Further, I understand that providing false or misleading information and/or omission of information by me about my Indigenous identity may result in an investigation and if the investigation is founded, will be grounds for immediate suspension of any funding and further, revocation of any Funding Agreement between me and the Native Women’s Association of Canada and/or its sub-agreement holders, and will result in a repayment of funds to Employment and Social Development Canada (ESDC), for monies I received to which I was not entitled.\", \"fr\": \"De plus, je comprends que la fourniture d\'informations fausses ou trompeuses et/ou l\'omission d\'informations par moi concernant ma identité autochtone peut entraîner une enquête et si l\'enquête est confirmée, sera les raisons d\'une suspension immédiate de toute subvention et de plus, de l\'annulation d\'un Accord de financement entre moi et l\'Association des Femmes Autochtones du Canada et/ou ses titulaires de sous-accords, et causera un remboursement de fonds à l\'Emploi et au Développement Social du Canada (ESDC), pour des monnaies dont je n\'étais pas éligible.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body\"}, {\"id\": \"indigenous-declaration\", \"hint\": {\"en\": \"I declare that I am an Indigenous person according to the following definition: Indigenous Peoples are people who are First Nations, Inuit or Métis.\", \"fr\": \"I declare that I am an Indigenous person according to the following definition: Indigenous Peoples are people who are First Nations, Inuit or Métis.\"}, \"type\": \"signature-ack\", \"label\": {\"en\": \"Declaration\", \"fr\": \"Declaration\"}, \"required\": true, \"normalize\": \"none\", \"boxPadding\": \"m\", \"clearLabel\": {\"en\": \"Clear\", \"fr\": \"Clear\"}, \"labelClass\": \"govuk-label--m\", \"storageKey\": \"indigenous_declaration\", \"actionLabel\": {\"en\": \"Sign Now\", \"fr\": \"Sign Now\"}, \"placeholder\": {\"en\": \"First Last\", \"fr\": \"First Last\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"en\": \"Signed\", \"fr\": \"Signed\"}, \"statusUnsignedText\": {\"en\": \"Not signed\", \"fr\": \"Not signed\"}}], \"nextStepId\": \"eligibility\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Eligibility\", \"fr\": \"Eligibility\"}, \"stepId\": \"eligibility\", \"components\": [{\"id\": \"paragraph\", \"text\": {\"en\": \"Eligibility Check\", \"fr\": \"Vérification de l\'éligibilité\"}, \"type\": \"paragraph\", \"class\": \"govuk-heading-l\"}, {\"id\": \"paragraph-2\", \"text\": {\"en\": \"Please answer the following questions to determine your eligibility for the ISET program.\", \"fr\": \"Répondez aux questions suivantes pour déterminer votre éligibilité au programme ISET.\"}, \"type\": \"paragraph\", \"class\": \"govuk-body-l\"}, {\"id\": \"eligibility-indigenous\", \"hint\": {\"en\": \"This program is for Indigenous Peoples: First Nations, Inuit, or Métis.\", \"fr\": \"Ce programme est destiné aux Peuples autochtones : First Nations, Inuit ou Métis.\"}, \"name\": \"eligibility-indigenous\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Are you a member of a First Nations, Inuit, or Métis group?\", \"fr\": \"Êtes-vous un membre d\'un groupe First Nations, Inuit ou Métis ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-indigenous\", \"validation\": {\"rules\": [{\"id\": \"eligibility-indigenous-required\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-indigenous\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"eligibility-female\", \"hint\": {\"en\": \"ISET is open to Indigenous women, trans women, Two-Spirit, and gender-diverse people who identify as women.\", \"fr\": \"ISET est ouvert aux femmes autochtones, aux trans femmes, aux personnes de l\'identité deux-esprits et aux personnes transgenres qui s\'identifient comme des femmes.\"}, \"name\": \"eligibility-female\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Do you identify as a woman, trans woman, Two-Spirit, or gender-diverse individual who identifies as a woman?\", \"fr\": \"Identifiez-vous-vous comme une femme, une trans femme, de l\'identité deux-esprits ou une personne transgenre qui s\'identifie comme une femme ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-female\", \"validation\": {\"rules\": [{\"id\": \"rule-1756933101438-0dxf\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-female\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"eligibility-canadian\", \"hint\": {\"en\": \"You must be a Canadian citizen to qualify for ISET funding.\", \"fr\": \"Vous devez être une citoyenne canadienne pour être éligible au financement ISET.\"}, \"name\": \"eligibility-canadian\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Are you a Canadian citizen?\", \"fr\": \"Êtes-vous une citoyenne canadienne ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-canadian\", \"validation\": {\"rules\": [{\"id\": \"rule-1757087157281-7u8s\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-canadian\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"eligibility-age\", \"hint\": {\"en\": \"Applicants must be at least 15 years old at the time of application.\", \"fr\": \"Les demandeurs de financement doivent avoir au moins 15 ans à la date de la demande.\"}, \"name\": \"eligibility-age\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Are you 15 years of age or older?\", \"fr\": \"Êtes-vous âgé(e) de 15 ans ou plus ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-age\", \"validation\": {\"rules\": [{\"id\": \"rule-1757087201429-sb6t\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-age\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"eligibility-employment\", \"hint\": {\"en\": \"You may qualify if you are not working, working less than you want, or at risk of losing your job.\", \"fr\": \"Vous pourriez être éligible si vous n\'avez pas de travail, si vous travaillez moins qu\'il vous faut ou si vous risquez de perdre votre emploi.\"}, \"name\": \"eligibility-employment\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Are you unemployed, under-employed, or at risk of unemployment?\", \"fr\": \"Êtes-vous sans emploi, sous-employé(e) ou à risque de chômage ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-employment\", \"validation\": {\"rules\": [{\"id\": \"rule-1757087215312-7enu\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-employment\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"eligibility-training\", \"hint\": {\"en\": \"This includes college, university, or other recognized training programs that help you get a job.\", \"fr\": \"Cela comprend les collèges, les universités ou d\'autres programmes de formation reconnus qui vous aident à trouver un emploi.\"}, \"name\": \"eligibility-training\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Are you pursuing or planning to pursue post-secondary training leading to employment?\", \"fr\": \"Suivez-vous ou planifiez-vous des études postsecondaires conduisant à un emploi ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-training\", \"validation\": {\"rules\": [{\"id\": \"rule-1757087227077-5qno\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-training\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"eligibility-financial\", \"hint\": {\"en\": \"ISET funding is for applicants whose education or training costs are not fully paid by other sources (e.g., Band, student loans).\", \"fr\": \"Le financement ISET est destiné aux demandeurs dont les frais d\'éducation ou de formation n\'ont pas tous été payés par d\'autres sources (par exemple, par la bande ou par des prêts étudiants).\"}, \"name\": \"eligibility-financial\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Do you have a financial need not fully covered by other funding?\", \"fr\": \"Avez-vous une nécessité financière non couverte par d\'autres financements ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-financial\", \"validation\": {\"rules\": [{\"id\": \"rule-1757087241712-unb6\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-financial\"}, \"no\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}, {\"id\": \"eligibility-disqualified\", \"hint\": {\"en\": \"If you have previously lost ISET funding due to default or other disqualification, you may not be eligible.\", \"fr\": \"Si vous avez déjà perdu le financement ISET à cause de défaut ou d\'autres raisons d\'exclusion, vous pourriez ne pas être éligible.\"}, \"name\": \"eligibility-disqualified\", \"type\": \"radio\", \"class\": \"govuk-radios--inline\", \"label\": {\"en\": \"Have you ever been disqualified from ISET funding due to default or other reasons?\", \"fr\": \"Avez-vous déjà été exclu(e) du financement ISET à cause de défaut ou d\'autres raisons ?\"}, \"options\": [{\"label\": {\"en\": \"Yes\", \"fr\": \"Oui\"}, \"value\": \"yes\"}, {\"label\": {\"en\": \"No\", \"fr\": \"Non\"}, \"value\": \"no\"}], \"required\": true, \"normalize\": \"yn-01\", \"storageKey\": \"eligibility-disqualified\", \"validation\": {\"rules\": [{\"id\": \"rule-1757087254780-h1kc\", \"type\": \"predicate\", \"when\": {\"==\": [{\"var\": \"eligibility-disqualified\"}, \"yes\"]}, \"block\": true, \"message\": {\"en\": \"You are not eligible to apply based on this answer.\", \"fr\": \"Vous n’êtes pas admissible à présenter une demande selon cette réponse.\"}, \"trigger\": [\"change\", \"submit\"], \"severity\": \"error\"}], \"required\": true, \"requiredMessage\": {\"en\": \"A response is required\", \"fr\": \"Une réponse est requise\"}}, \"legendClass\": \"govuk-fieldset__legend--s\"}], \"nextStepId\": \"social-insurance-number\", \"description\": {\"en\": \"\", \"fr\": \"\"}}, {\"type\": \"schema\", \"title\": {\"en\": \"Social Insurance Number\", \"fr\": \"Social Insurance Number\"}, \"stepId\": \"social-insurance-number\", \"components\": [{\"id\": \"social-insurance-number\", \"hint\": {\"en\": \"We need your Social Insurance Number to process your request. It will only be used to confirm your eligibility and won’t be shared without your permission.  Your 9-digit Social Insurance Number (e.g., 123 456 789)\", \"fr\": \"Nous avons besoin de votre numéro d\'assurance sociale pour traiter votre demande. Il ne sera uti